<template>
  <div class="min-h-screen px-4 py-8 sm:px-6 lg:px-8"><div class="mx-auto max-w-6xl space-y-6">
    <PageHeader :title="t('admin_billing.organization_detail_title')" :description="t('admin_billing.organization_detail_desc')" back-to="/admin/billing/organizations" />
    <PageState :loading="loading" :error="error" :empty="!organization" :empty-text="t('admin_billing.organization_not_found')" @retry="load"><template v-if="organization">
      <section class="detail-card"><div class="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><h2 class="text-2xl font-black dark:text-white">{{ organization.name }}</h2><p class="mt-1 text-sm text-slate-500">{{ organization.owner?.name || '—' }} · {{ organization.owner?.email || '—' }}</p></div><div class="flex flex-wrap gap-2"><StatusBadge :status="organization.status"/><StatusBadge :status="organization.plan_status"/></div></div>
        <div class="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><button class="action-button bg-cyan-600 text-white" @click="openAction('change-plan')">{{ t('admin_billing.change_plan') }}</button><button class="action-button bg-indigo-600 text-white disabled:cursor-not-allowed disabled:opacity-40" :disabled="isDefault" :title="isDefault ? t('admin_billing.default_no_expiry_short') : ''" @click="openAction('extend')">{{ isDefault ? t('admin_billing.default_no_expiry_long') : t('admin_billing.extend') }}</button><button class="action-button bg-emerald-600 text-white" @click="openAction('grant')">{{ t('admin_billing.action_grant') }}</button><button class="action-button bg-amber-500 text-slate-950" @click="openAction('deduct')">{{ t('admin_billing.action_deduct') }}</button><button class="action-button bg-rose-600 text-white" @click="openAction('reset')">{{ t('admin_billing.action_reset') }}</button></div>
      </section>
      <div class="grid gap-4 lg:grid-cols-2"><section class="detail-card"><h3 class="section-title">{{ t('admin_billing.subscription') }}</h3><dl class="detail-grid"><div><dt>{{ t('admin_billing.current_plan') }}</dt><dd class="uppercase">{{ organization.plan_type }}</dd></div><div><dt>{{ t('admin_billing.previous_plan') }}</dt><dd class="uppercase">{{ organization.previous_plan_type || '—' }}</dd></div><div><dt>{{ t('admin_billing.start') }}</dt><dd>{{ formatBillingDate(organization.plan_started_at, true) }}</dd></div><div><dt>{{ t('admin_billing.expiry') }}</dt><dd>{{ formatBillingDate(organization.plan_expires_at, true) }}</dd></div><div><dt>{{ t('admin_billing.remaining') }}</dt><dd>{{ organization.days_remaining === null ? t('admin_billing.no_expiry') : `${organization.days_remaining} ${t('admin_billing.days')}` }}</dd></div><div><dt>{{ t('admin_billing.chatbots') }}</dt><dd>{{ formatBillingNumber(organization.chatbots_count) }}</dd></div></dl></section>
      <section class="detail-card"><h3 class="section-title">{{ t('admin_billing.token_wallet') }}</h3><dl class="detail-grid"><div><dt>{{ t('admin_billing.token_limit') }}</dt><dd>{{ formatBillingLimit(organization.tokens_limit) }}</dd></div><div><dt>{{ t('admin_billing.plan_tokens_remaining') }}</dt><dd>{{ formatBillingLimit(organization.plan_remaining_tokens) }}</dd></div><div><dt>{{ t('admin_billing.topup_tokens') }}</dt><dd>{{ formatBillingNumber(organization.topup_tokens) }}</dd></div><div><dt>{{ t('admin_billing.header_remaining') }}</dt><dd>{{ formatBillingLimit(organization.remaining_tokens) }}</dd></div><div><dt>{{ t('admin_billing.used') }}</dt><dd>{{ formatBillingNumber(organization.tokens_used) }}</dd></div></dl></section></div>
      <section class="detail-card"><h3 class="section-title">{{ t('admin_billing.latest_payment') }}</h3><template v-if="organization.latest_payment"><dl class="detail-grid sm:grid-cols-4"><div><dt>{{ t('admin_billing.header_order_code') }}</dt><dd class="font-mono">{{ organization.latest_payment.order_code }}</dd></div><div><dt>{{ t('admin_billing.header_status') }}</dt><dd>{{ organization.latest_payment.status }}</dd></div><div><dt>{{ t('admin_billing.header_amount') }}</dt><dd>{{ formatBillingMoney(organization.latest_payment.amount, organization.latest_payment.currency_snapshot || organization.latest_payment.currency || 'VND') }}</dd></div><div><dt>{{ t('admin_billing.header_time') }}</dt><dd>{{ formatBillingDate(organization.latest_payment.created_at, true) }}</dd></div></dl></template><p v-else class="text-sm text-slate-500">{{ t('admin_billing.no_payment') }}</p><p class="mt-4 text-xs text-slate-500">{{ t('admin_billing.total_payments', { count: formatBillingNumber(organization.payments_count) }) }}</p></section>
    </template></PageState>
    <OrganizationActionModal v-if="organization" v-model="actionOpen" :mode="actionMode" :organization="organization" :plans="plans" :busy="busy" :server-errors="fieldErrors" @submit="performAction" />
  </div></div>
</template>

<script setup lang="ts">
import type { AdminBillingOrganization, BillingPlan, FieldErrors } from '~/types/admin-billing'; import PageHeader from '~/components/admin/billing/PageHeader.vue'; import PageState from '~/components/admin/billing/PageState.vue'; import StatusBadge from '~/components/admin/billing/StatusBadge.vue'; import OrganizationActionModal from '~/components/admin/billing/OrganizationActionModal.vue'; import { formatBillingDate, formatBillingLimit, formatBillingMoney, formatBillingNumber } from '~/utils/adminBilling'
const { t } = useI18n()
type Mode = 'change-plan'|'extend'|'grant'|'deduct'|'reset'; definePageMeta({ layout: 'layout-admin' }); const route = useRoute(); const api = useAdminBilling(); const toast = useToast(); const organization = ref<AdminBillingOrganization | null>(null); const plans = ref<BillingPlan[]>([]); const loading = ref(true); const error = ref(''); const busy = ref(false); const actionOpen = ref(false); const actionMode = ref<Mode>('change-plan'); const fieldErrors = ref<FieldErrors>({}); const isDefault = computed(() => Boolean(organization.value?.plan_is_default))
const load = async () => { loading.value = true; error.value = ''; try { organization.value = (await api.getOrganization(String(route.params.id))).data } catch (e) { error.value = getAdminBillingErrorMessage(e) } finally { loading.value = false } }; const loadPlans = async () => { try { plans.value = (await api.listPlans({ per_page: 100 })).data } catch (e) { toast.error(getAdminBillingErrorMessage(e)) } }; const openAction = (mode: Mode) => { actionMode.value = mode; fieldErrors.value = {}; actionOpen.value = true }
const performAction = async (payload: { mode: Mode; billingPlanId?: number; billingCycle?: 'monthly'|'annual'; months?: number; amount?: number; reason: string }) => { if (!organization.value || busy.value) return; busy.value = true; fieldErrors.value = {}; try { let response; if (payload.mode === 'change-plan') response = await api.changeOrganizationPlan(organization.value.id, payload.billingPlanId!, payload.billingCycle!, payload.reason); else if (payload.mode === 'extend') response = await api.extendOrganization(organization.value.id, payload.months!, payload.reason); else if (payload.mode === 'grant') response = await api.grantOrganizationTokens(organization.value.id, payload.amount!, payload.reason); else if (payload.mode === 'deduct') response = await api.deductOrganizationTokens(organization.value.id, payload.amount!, payload.reason); else response = await api.resetOrganizationPlanTokens(organization.value.id, payload.reason); organization.value = response.data; toast.success(t('admin_billing.organization_updated')); actionOpen.value = false } catch (e) { if (e instanceof AdminBillingError) fieldErrors.value = e.errors; toast.error(getAdminBillingErrorMessage(e)) } finally { busy.value = false } }
onMounted(() => { load(); loadPlans() })
</script>
<style scoped>.detail-card{ @apply rounded-2xl border border-slate-200 bg-white p-5 shadow-sm dark:border-white/10 dark:bg-white/5; }.section-title{ @apply mb-5 text-base font-extrabold text-slate-900 dark:text-white; }.detail-grid{ @apply grid gap-5 sm:grid-cols-2; }dt{ @apply text-xs font-bold uppercase tracking-wide text-slate-500; }dd{ @apply mt-1 font-semibold text-slate-900 dark:text-slate-100; }.action-button{ @apply rounded-xl px-3 py-2.5 text-sm font-bold transition hover:brightness-105 disabled:hover:brightness-100; }</style>
